/**
 * Petshop Sargas Likucio grazinimas v1.0 (atsaukimo patikra)
 *
 * LAIKINAS SARGAS (S1661/S1662): pay-page kelias istrina _reduced_stock,
 * todel atsaukimas gali tyliai negrazinti likucio. Sis sargas nieko nekeicia —
 * tik pazymi uzsakyma ispejimo pastaba, jei mazinimas buvo, o grazinimo nera.
 * Salinti, kai bus rasta ir sutvarkyta tikroji trynimo vieta.
 */
add_action('woocommerce_order_status_cancelled', function($oid){
	$o = wc_get_order($oid); if (!$o) return;
	global $wpdb;
	$maz = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->comments} WHERE comment_post_ID=%d AND comment_type='order_note' AND (comment_content LIKE 'Likutis sumažintas%%' OR comment_content LIKE 'Stock levels reduced%%')", $oid));
	if (!$maz) return;
	$grz = (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->comments} WHERE comment_post_ID=%d AND comment_type='order_note' AND (comment_content LIKE 'Likutis padidintas%%' OR comment_content LIKE '%%AV grąžinimas%%' OR comment_content LIKE 'Stock levels increased%%' OR comment_content LIKE '%%rankiniu būdu S16%%')", $oid));
	if ($grz) return;
	$o->add_order_note('⚠ SARGAS: likutis buvo sumažintas, bet atšaukiant NEGRĮŽO — grąžink rankiniu ir patikrink eilutės _reduced_stock. (Petshop Sargas v1.0)');
}, 99);
